const assetModuleURL=import.meta.url;const base=new URL('../gohyeon-native/native_candidate/',assetModuleURL);
export const sha=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');const json=b=>JSON.parse(new TextDecoder().decode(b));
export function scope({fetcher=fetch,decode=b=>createImageBitmap(new Blob([b])),signal}={}){let dead=false;const images=[],closed=new WeakSet(),errors=[],cleanups=[];const check=()=>{if(dead||signal?.aborted)throw Error('S4_PREPARE_ABORTED')};const close=im=>{if(im&&!closed.has(im)){closed.add(im);try{im.close?.()}catch(e){errors.push(String(e))}}};const dispose=()=>{if(dead)return;dead=true;signal?.removeEventListener('abort',dispose);for(const im of images)close(im);images.length=0;for(const f of cleanups.splice(0)){try{f()}catch(e){errors.push(String(e))}}};const raw=async u=>{check();const r=await fetcher(u,{signal});check();if(!r.ok)throw Error('S4_INPUT_MISSING');const b=new Uint8Array(await r.arrayBuffer()).slice();check();return b};const pinned=async(u,pin,bytes)=>{const b=await raw(u);if(bytes!==undefined&&b.length!==bytes||await sha(b)!==pin)throw Error('S4_INPUT_PIN');check();return b};const image=async(b,w,h)=>{check();const im=await decode(b);if(dead||signal?.aborted){close(im);check()}images.push(im);check();if(im.width!==w||im.height!==h)throw Error('S4_IMAGE_DIMENSION');return im};const wrappedFetch=async u=>{const b=await raw(u);return{ok:true,arrayBuffer:async()=>b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength)}};signal?.addEventListener('abort',dispose,{once:true});return{check,pinned,image,wrappedFetch,dispose,onCleanup(f){if(dead)f();else cleanups.push(f)},releaseImage(im){close(im);const i=images.indexOf(im);if(i>=0)images.splice(i,1)},get dead(){return dead},get errors(){return [...errors]}};}

export function dataRecord(o,allowed,required=allowed){if(!o||Object.getPrototypeOf(o)!==Object.prototype)throw Error('S4_PLAIN_DATA_REQUIRED');const keys=Reflect.ownKeys(o),v={};if(keys.some(k=>typeof k!=='string'||!allowed.includes(k))||required.some(k=>!keys.includes(k)))throw Error('S4_EXACT_FIELDS');for(const k of keys){const d=Object.getOwnPropertyDescriptor(o,k);if(!d?.enumerable||!Object.hasOwn(d,'value'))throw Error('S4_DATA_DESCRIPTOR');v[k]=d.value}return v}
export function footData(f){if(!Array.isArray(f)||Object.getPrototypeOf(f)!==Array.prototype||Reflect.ownKeys(f).length!==3)throw Error('S4_FOOT_DATA');const a=Object.getOwnPropertyDescriptor(f,'0'),b=Object.getOwnPropertyDescriptor(f,'1'),l=Object.getOwnPropertyDescriptor(f,'length');if(!a?.enumerable||!b?.enumerable||!Object.hasOwn(a,'value')||!Object.hasOwn(b,'value')||l?.value!==2||!Number.isInteger(a.value)||!Number.isInteger(b.value))throw Error('S4_FOOT_DATA');return[a.value,b.value]}

export async function loadPlayers(s,appearance,make){const frames={};if(appearance==='boy'){const actorBase=new URL('../../gohyeon-pair/player_frames/',base),am=json(await s.pinned(new URL('PLAYER_FRAME_RECOVERY.json',actorBase),'114146904e6df960a4bc215a523b6e4aa7aa55c6df5d4e4a92966815fed86f20'));for(const f of am.frames)frames[f.frame]=await s.image(await s.pinned(new URL(f.path,actorBase),f.sha256),107,107);if(Object.keys(frames).length!==12)throw Error('S4_BOY12_REQUIRED')}else{const manifestURL=new URL('../../../assets/approved-atlases/manifest.json',base),am=json(await s.pinned(manifestURL,'3f337223b51724f825810ff0a15a6eecbb02897a1202f836342f35a9272ff4cc')),pin=am.atlases['player/PLAYER_FEMALE'],atlas=await s.image(await s.pinned(new URL('../../../'+pin.src,base),pin.sha256),pin.width,pin.height);for(let i=0;i<12;i++){const f=am.frames.player['PLAYER_FEMALE.'+['FRONT','RIGHT','LEFT','BACK'][Math.floor(i/3)]+'.'+['IDLE','A','B'][i%3]];if(!f||f.atlas!=='player/PLAYER_FEMALE')throw Error('S4_GIRL_FRAME');const c=make(107,107),ctx=c.getContext('2d'),sc=80/192;ctx.imageSmoothingEnabled=false;ctx.drawImage(atlas,...f.rect,53-f.anchor[0]*sc,90-f.anchor[1]*sc,f.width*sc,f.height*sc);frames[i]=c}s.releaseImage(atlas)}return Object.fromEntries(Object.entries(frames).map(([k,v])=>['actor:'+k,v]))}
export function visibleView({s,support,appearance,make,drawNative,gym=false}){let receipt=null,last=null,generation=0;const invalidateFrame=()=>{receipt=last=null;generation++};s.onCleanup(invalidateFrame);const stage=make(960,540),ctx=stage.getContext('2d');const capture=input=>{const v=dataRecord(input,['foot','facing','state','minutes','elapsedMs','walking','water','leaf','lights','rest'],['foot','facing','state','minutes','elapsedMs']);if(!Number.isFinite(v.minutes)||v.minutes<0||v.minutes>=1440||!Number.isFinite(v.elapsedMs)||v.elapsedMs<0)throw Error('S4_TARGET_CLOCK');for(const k of['walking','water','leaf','lights','rest'])if(v[k]!==undefined&&typeof v[k]!=='boolean')throw Error('S4_TARGET_OPTION');const pose=support.describe(footData(v.foot),v.facing,v.state);return{pose,appearance,walking:v.walking===true,clock:{minutes:v.minutes,elapsedMs:v.elapsedMs,water:v.water!==false,leaf:v.leaf!==false,lights:v.lights!==false,rest:v.rest===true}}},key=v=>JSON.stringify(v);
return Object.freeze({get pinsVerified(){return!s.dead&&support.pinsVerified},describe:support.describe,validate:support.validate,safe:support.safe,currentFrame:()=>s.dead?null:receipt,invalidateFrame,frameMatchesState(token,pose,input){if(!token||token!==receipt||s.dead)return false;try{return support.validate(pose)&&key(capture(input))===key(last)&&pose.foot[0]===last.pose.foot[0]&&pose.foot[1]===last.pose.foot[1]&&pose.facing===last.pose.facing&&pose.state===last.pose.state}catch{return false}},draw(destination,input){invalidateFrame();s.check();if(destination.isContextLost?.()===true||destination.canvas.width!==960||destination.canvas.height!==540)throw Error('S4_TARGET_VIEWPORT');const v=capture(input),gen=generation;const result=drawNative(ctx,v);if(result===false)return false;s.check();destination.drawImage(stage,0,0);s.check();if(destination.isContextLost?.()===true||destination.canvas.width!==960||destination.canvas.height!==540)throw Error('S4_TARGET_CONTEXT_LOST');if(gen!==generation)throw Error('S4_TARGET_DRAW_INVALIDATED');last=v;receipt=Object.freeze({});return true},dispose:()=>s.dispose(),get cleanupErrors(){return s.errors}})}
